-- Faculty and classes, generated by: python -m scheduler web
begin;
create schema if not exists seed;
drop table if exists seed.faculty, seed.classes, seed.class_moves;
create table seed.faculty (key text primary key, name text, college text, department text, rank text, designation text, max_lu int, degree text, specialization text);
-- Specializations come from the loading plans, and one typed on the Faculty Profiles page is kept.
select key, name, college, department, rank, designation, max_lu, degree, specialization from seed.faculty
on conflict (key) do update set name = excluded.name, college = excluded.college, department = excluded.department, rank = excluded.rank, designation = excluded.designation, max_lu = excluded.max_lu, degree = excluded.degree, specialization = coalesce(public.faculty.specialization, excluded.specialization);
-- CISC is now CICS. Move what points at the old faculty keys to the new ones.
update public.faculty n set specialization = o.specialization from public.faculty o
  where o.key like 'CISC-%' and n.key = 'CICS-' || substr(o.key, 6) and o.specialization is not null;
update public.classes set plan_teacher = 'CICS-' || substr(plan_teacher, 6) where plan_teacher like 'CISC-%';
update public.teacher_changes set teacher = 'CICS-' || substr(teacher, 6) where teacher like 'CISC-%';
update public.ge_decisions set teacher = 'CICS-' || substr(teacher, 6) where teacher like 'CISC-%';
update public.staff set college = 'CICS' where college = 'CISC';
update public.ge_requests set college = 'CICS' where college = 'CISC';
update public.instructor_requests set college = 'CICS' where college = 'CISC';
update public.submissions set college = 'CICS' where college = 'CISC';
-- Faculty no longer in the plans: clear the classes given to them, then remove them.
update public.classes set plan_teacher = null where plan_teacher is not null and plan_teacher not in (select key from seed.faculty);
delete from public.teacher_changes where teacher is not null and teacher not in (select key from seed.faculty);
update public.ge_decisions set teacher = null where teacher is not null and teacher not in (select key from seed.faculty);
delete from public.faculty where key not in (select key from seed.faculty);
create table seed.classes (id text primary key, sem int, course text, section text, program text, college text, department text, is_ge boolean, plan_teacher text, house_dept text, house_college text);
select id, sem, course, section, program, college, department, is_ge, plan_teacher, house_dept, house_college from seed.classes
on conflict (id) do update set course = excluded.course, section = excluded.section, program = excluded.program, college = excluded.college, department = excluded.department, is_ge = excluded.is_ge, plan_teacher = excluded.plan_teacher, house_dept = excluded.house_dept, house_college = excluded.house_college;
-- Move what was booked under older class ids to the same course and section.
create table seed.class_moves as
  select o.id as old_id, n.id as new_id from public.classes o
  join seed.classes n on n.sem = o.sem and n.course = o.course
   and (n.section = o.section or (o.section ~ '^(ABC|ABEcon|BLIS|BSEntrep) [1-4]A$' and n.section = left(o.section, -1)))
  where o.sem = 1 and o.id not in (select id from seed.classes);
update public.bookings b set class_id = m.new_id from seed.class_moves m
  where b.class_id = m.old_id and not exists (select 1 from public.bookings x where x.class_id = m.new_id and x.part = b.part);
update public.teacher_changes t set class_id = m.new_id from seed.class_moves m
  where t.class_id = m.old_id and not exists (select 1 from public.teacher_changes x where x.class_id = m.new_id);
update public.ge_requests t set class_id = m.new_id from seed.class_moves m
  where t.class_id = m.old_id and not exists (select 1 from public.ge_requests x where x.class_id = m.new_id);
update public.ge_decisions t set class_id = m.new_id from seed.class_moves m
  where t.class_id = m.old_id and not exists (select 1 from public.ge_decisions x where x.class_id = m.new_id);
update public.instructor_requests t set class_id = m.new_id from seed.class_moves m
  where t.class_id = m.old_id and not exists (select 1 from public.instructor_requests x where x.class_id = m.new_id);
-- Classes no longer in the curricula go, with whatever was booked for them.
delete from public.classes where sem = 1 and id not in (select id from seed.classes);
-- Departments that may teach each GE course (kept as edited on the Settings page).
update public.ge_teachers set college = 'CICS' where college = 'CISC';
on conflict (course, department) do nothing;
-- The working tables of this script are no longer needed.
drop schema seed cascade;
commit;
